// Increase t with corrected step size
t=lt+ilen*.0007;
// Calculate ox/oy/oz now
ox=cos(t)*cos(t*.379+1)*cos(sin(t*.141));
oy=sin(t*.91)*cos(-t*.71)*.5;
oz=-(sin(t)*cos(-t*.41)*sin(cos(t*.631)));
ot=.4+.7/sqrt(sqr(ox)+sqr(oy)+sqr(oz));
